import {test} from 'node:test';import assert from 'node:assert/strict';
import {quests,assignmentData,makeHomeworkDraft,homeworkState,homeworkSummary,paperTrade,resolveQuest,displayEntryBody} from '../hw-core.test.mjs';
const good={status:'ready',attempt:'I made the practice folder and compared a claim.',observation:'The expected result was checked.',next:'Try the next question.',answer:1};
function entry(draft){return {...draft,id:'fixture',created_at:'2026-09-11T00:00:00Z',scope:'device-local',authority:'none',acceptance:'self-reported',previous:'0'.repeat(64),hash:'a'.repeat(64)};}
test('ten requested areas exist, assigned by Steven',()=>{assert.equal(quests.length,10);assert.equal(assignmentData.assigned_by,'Steven');for(const id of ['ai-prep','claude-account','first-code','hermes','claude-code','obs','x-account','agenc','frontrunner','crypto-lab'])assert.ok(resolveQuest(id));});
test('every tutorial is a puzzle, experiment, hints and evidence',()=>{for(const q of quests){assert.equal(q.steps.length,3);assert.equal(q.hints.length,2);assert.ok(q.proof.length>25);assert.equal(q.check.choices.length,3);assert.ok(q.sources.length>0);}});
test('only expected official source domains',()=>{const allow=new Set(['support.claude.com','code.claude.com','hermes-agent.nousresearch.com','github.com','developer.mozilla.org','obsproject.com','help.x.com','agenc.ag','support.google.com','www.investor.gov','ethereum.org']);for(const s of Object.values(assignmentData.sources))assert.ok(allow.has(new URL(s.url).hostname));});
test('unknown homework cannot be silently created',()=>assert.throws(()=>resolveQuest('secret-steven-task')));
test('ready is candidate, never approved/completed authority',()=>{const d=makeHomeworkDraft('ai-prep',good);assert.equal(d.state,'candidate');const body=JSON.parse(d.body);assert.equal(body.review,'not-submitted');assert.equal(body.assigned_by,'Steven');assert.equal(d.authority,undefined);});
test('blank evidence or wrong check blocks ready',()=>{assert.throws(()=>makeHomeworkDraft('ai-prep',{...good,observation:''}));assert.throws(()=>makeHomeworkDraft('ai-prep',{...good,answer:0}));});
test('missing attempt rejected',()=>assert.throws(()=>makeHomeworkDraft('ai-prep',{...good,attempt:' '})));
test('invalid status rejected',()=>assert.throws(()=>makeHomeworkDraft('ai-prep',{...good,status:'approved'})));
test('blocker needs next question but not a perfect quiz',()=>{assert.throws(()=>makeHomeworkDraft('frontrunner',{...good,status:'blocked',next:''}));assert.equal(JSON.parse(makeHomeworkDraft('frontrunner',{...good,status:'blocked',answer:null}).body).status,'blocked');});
test('unverified extension cannot be marked ready',()=>assert.throws(()=>makeHomeworkDraft('frontrunner',good)));
test('bounded notes',()=>assert.throws(()=>makeHomeworkDraft('ai-prep',{...good,attempt:'x'.repeat(1801)})));
test('latest valid record is shown; prior content retained',()=>{const a=entry(makeHomeworkDraft('ai-prep',{...good,status:'started'})),b=entry(makeHomeworkDraft('ai-prep',good));const list=[a,b];assert.equal(homeworkState(list)['ai-prep'].value.status,'ready');assert.equal(list.length,2);});
test('unrelated or conflicting record is not homework',()=>{const d=entry(makeHomeworkDraft('ai-prep',good));assert.deepEqual(homeworkState([{...d,source:'typed-here'},{...d,body:'{}'},{...d,body:d.body.replace('"assignment":"ai-prep"','"assignment":"hermes"')}]),{});});
test('check-in is human-readable and not a sending claim',()=>{const summary=homeworkSummary([entry(makeHomeworkDraft('ai-prep',good))]);assert.ok(summary.includes('not sent or teacher-approved'));assert.ok(summary.includes('ready to show'));assert.ok(summary.includes('not started'));});
test('existing field-log presentation is human-readable',()=>{const e=entry(makeHomeworkDraft('ai-prep',good));assert.ok(displayEntryBody(e).startsWith('HW learner report'));assert.equal(displayEntryBody({...e,source:'typed-here'}),e.body);});
test('rising price can lose after both fees',()=>{const p=paperTrade({quantity:10,entry:100,exit:102,fee:1,slippage:0});assert.ok(Math.abs(p.debit-1010)<1e-9);assert.ok(Math.abs(p.credit-1009.8)<1e-9);assert.ok(Math.abs(p.net+.2)<1e-9);});
test('slippage makes the sample worse',()=>assert.ok(paperTrade({quantity:10,entry:100,exit:102,fee:1,slippage:1}).net<-.2));
test('paper lab rejects nonfinite and invalid values',()=>{for(const patch of [{entry:NaN},{quantity:-1},{fee:11},{slippage:-1},{exit:-1},{entry:0}])assert.throws(()=>paperTrade({quantity:10,entry:100,exit:102,fee:1,slippage:0,...patch}));});

